"""Original environmental emergencies: heat and cold injury (16 questions)."""
from qbank_authoring import question,ref
rows=[]
HE=ref('Wilderness Medical Society heat illness guideline: 2024','https://doi.org/10.1177/10806032241227924')
FR=ref('Wilderness Medical Society frostbite guideline: 2024','https://doi.org/10.1177/10806032231222359')
RC=ref('Resuscitation Council UK special circumstances: 2025','https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/special-circumstances-guidelines')
def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('A runner collapses during a hot race with confusion, ataxia and a rectal temperature of 40.6°C. Which diagnosis is most likely?', 'Exertional heatstroke',[
 ('Heat exhaustion','Major CNS dysfunction indicates a more severe syndrome.'),('Simple exercise-associated collapse from venous pooling','This does not explain the marked hyperthermia and neurological dysfunction.'),('Uncomplicated heat cramps','Painful muscle spasm does not account for altered mental status.')],
 'Neurological dysfunction marks dangerous heat illness','**Heatstroke combines environmental/exertional heat stress with CNS impairment.**',['Temperature may already be lower after cooling or delay.','Sweating can still be present, especially in exertional disease.'],'**Begin rapid cooling with immediate ABC assessment.**',['Check glucose and evaluate other collapse causes concurrently.','Monitor for evolving multiorgan injury after temperature falls.'],[['Heat exhaustion','No major CNS dysfunction'],['Heatstroke','CNS dysfunction'],['Sweating','Does not exclude heatstroke']],[HE],style='clinical_scenario')

q('Which temperature measurement is preferred for an accurate core assessment in suspected exertional heatstroke in the field?', 'Rectal temperature using an appropriate probe',[
 ('Forehead infrared temperature','Environmental exposure and sweating can make it misleading.'),('Oral temperature immediately after drinking cold water','This can underestimate core temperature.'),('Axillary temperature after removing wet clothing','This is not a reliable measure of marked core hyperthermia.')],
 'Surface temperature may not reflect the dangerous core burden','**Rectal measurement is the preferred field core assessment in this context.**',['Do not delay cooling if the clinical syndrome strongly indicates heatstroke.','Measurement technique and ongoing reassessment matter.'],'**Use temperature and clinical response to guide cooling.**',['A low peripheral reading should not overrule a compatible collapse syndrome.','Provide airway access and monitoring during cooling.'],[['Preferred field core','Rectal'],['Surface devices','Potential underestimation'],['Treatment','Do not delay for perfect measurement']],[HE])

q('For severe exertional heatstroke when personnel and safe airway access are available, which cooling method is preferred?', 'Prompt cold-water immersion',[
 ('Ice packs to the neck and groin alone as equally rapid definitive cooling','Limited surface coverage usually cools more slowly.'),('Antipyretic medication followed by observation','Heatstroke is not a raised hypothalamic fever set point.'),('Delayed cooling until arrival at a distant hospital','Delay prolongs heat exposure and organ injury.')],
 'Cooling speed influences tissue injury','**Cold-water immersion provides rapid whole-body heat transfer.**',['Maintain airway safety and resuscitation access.','Use effective alternative conductive/evaporative methods if immersion is unavailable.'],'**Cool immediately while organizing transfer and ongoing monitoring.**',['Do not leave the patient unattended in water.','Stop aggressive cooling at the protocol endpoint to avoid overshoot.'],[['Preferred','Cold-water immersion'],['Alternative','Effective conductive/evaporative cooling'],['Avoid','Transport-related cooling delay']],[HE])

q('Why are acetaminophen and NSAIDs not useful treatments for heatstroke hyperthermia?', 'The principal problem is excess heat load and failed dissipation rather than a prostaglandin-mediated fever set point',[
 ('They cool at the same speed as immersion but are less convenient','They do not replace physical heat removal.'),('They reliably prevent heatstroke-associated liver injury','They have no such protective role and can add toxicity.'),('They correct the associated coagulation disorder directly','They do not reverse heat-related systemic injury.')],
 'Hyperthermia requires heat removal','**Antipyretics target fever pathways rather than the heatstroke mechanism.**',['Heatstroke can involve hepatic and renal injury.','Drug adverse effects can complicate an already injured patient.'],'**Use physical cooling and physiological support.**',['Treat seizures, hypoglycemia and shock when present.','Reassess organ function over time rather than declaring recovery from a normal temperature alone.'],[['Fever','Altered thermoregulatory set point'],['Heatstroke','Heat accumulation'],['Effective immediate treatment','Cooling']],[HE])

q('A heatstroke patient is awake after cooling but develops rising INR, aminotransferases and creatinine over the next day. Which interpretation is correct?', 'Delayed multiorgan injury can progress despite initial neurological and temperature improvement',[
 ('Normal temperature excludes further heat-related injury','Inflammatory, coagulation and cellular injury can continue.'),('The findings establish isolated viral hepatitis','Alternative causes need evaluation, but the heatstroke context is highly relevant.'),('The initial response proves that monitoring is no longer needed','Laboratory deterioration can be delayed.')],
 'Cooling ends heat exposure, not necessarily every downstream process','**Heatstroke may cause hepatic failure, AKI, rhabdomyolysis and coagulopathy.**',['Follow serial organ function and perfusion.','Assess other causes and contributing exposures when appropriate.'],'**Escalate support and specialist referral for progressive organ failure.**',['Early liver-center discussion is appropriate for severe synthetic failure/encephalopathy.','Continue careful fluid and electrolyte management.'],[['Initial improvement','Does not guarantee full recovery'],['Later injury','Liver/kidney/coagulation'],['Disposition','Based on evolving severity']],[HE],style='clinical_scenario')

q('A confused marathon runner has sodium 121 mmol/L and a core temperature of 38.0°C after drinking large volumes of water. Which diagnosis is the main concern?', 'Exercise-associated hyponatremic encephalopathy',[
 ('Heatstroke established solely by the race setting','The sodium and lack of marked core hyperthermia point to a different urgent mechanism.'),('Simple dehydration requiring unrestricted hypotonic water','Additional free water can worsen cerebral edema.'),('Uncomplicated muscle cramps','Confusion with marked hyponatremia is a neurological emergency.')],
 'Not all hot-event collapse is heatstroke','**Excess fluid intake with impaired water excretion can cause acute hypotonic hyponatremia.**',['The syndromes can coexist, so measure both sodium and core temperature.','Severe neurological symptoms need an emergency hypertonic-saline pathway.'],'**Avoid indiscriminate additional water and treat the demonstrated physiology.**',['Provide airway/seizure support if needed.','Monitor sodium response closely after treatment.'],[['Heatstroke','Heat/CNS syndrome'],['EAH','Low sodium with compatible intake'],['Treatment distinction','Cooling versus controlled hypertonic therapy as indicated']],[HE,ref('European hyponatraemia guideline','https://academic.oup.com/ejendo/article/170/3/G1/6668028')],style='clinical_scenario')

q('Which medication group can increase heat-illness risk by reducing sweating?', 'Antimuscarinic drugs',[
 ('Acetylcholinesterase inhibitors through complete sweat suppression','Cholinergic stimulation tends to increase secretory activity.'),('Oral rehydration salts through muscarinic blockade','These do not block sweating receptors.'),('Loop diuretics through direct muscarinic antagonism','They can increase dehydration risk but not through this stated mechanism.')],
 'Risk factors can alter heat production or heat loss','**Sweat glands depend on sympathetic cholinergic signaling.**',['Muscarinic blockade can reduce evaporative cooling.','Sedatives, stimulants and volume-depleting drugs can add risk through other mechanisms.'],'**Review medicines and environmental exposure in vulnerable patients.**',['Plan hydration and cooling access without encouraging excessive water intake.','Recognize that age and comorbidity can impair adaptation.'],[['Antimuscarinic','Impaired sweating'],['Diuretic','Volume depletion risk'],['Stimulant','Increased heat generation/activity']],[HE])

q('Which prevention strategy best supports safe adaptation to repeated exercise in heat?', 'Progressive heat acclimatization with adjusted workload, rest and access to fluids and cooling',[
 ('A single maximal session without rest to force adaptation','This raises acute heat-illness risk.'),('Salt tablets alone regardless of fluid intake and workload','No single supplement replaces exposure and workload management.'),('Drinking beyond thirst to maximize body-weight gain during every event','Excessive intake can cause exercise-associated hyponatremia.')],
 'Adaptation requires graded exposure','**Acclimatization improves thermoregulatory and cardiovascular responses.**',['Work intensity, humidity, clothing and individual illness affect risk.','Recent febrile illness and poor recovery can reduce tolerance.'],'**Use an organized heat-safety and emergency-cooling plan.**',['Adjust activity to conditions rather than relying only on ambient temperature.','Educate participants to recognize early symptoms and stop activity.'],[['Adaptation','Graded exposure'],['Risk control','Work/rest/environment'],['Hydration','Avoid both depletion and overdrinking']],[HE])

q('A cold-exposed patient is confused, no longer shivering and has a core temperature of 29°C. Which statement is correct?', 'This is clinically significant hypothermia requiring gentle handling and active rewarming with monitored care',[
 ('Absence of shivering proves that the patient is warm enough','Shivering may cease as hypothermia worsens.'),('Vigorous limb exercise is the safest immediate rewarming method','This can destabilize a severely cold patient.'),('The temperature alone proves irreversible death','Hypothermic patients can recover with appropriate treatment.')],
 'Loss of shivering is not reassurance','**CNS and cardiovascular function decline as core temperature falls.**',['Handle gently, prevent further heat loss and assess breathing/circulation carefully.','Use a low-reading core thermometer and appropriate monitoring.'],'**Select rewarming and transfer according to stability and severity.**',['Remove wet clothing in a protected environment.','Severe instability or arrest may require an extracorporeal rewarming center.'],[['Core temperature','29°C'],['Clinical signs','Impaired consciousness/no shivering'],['Priority','Protected monitored rewarming']],[RC],style='clinical_scenario')

q('What does afterdrop describe during rescue from cold exposure?', 'Continued decline in core temperature after removal from the cold environment',[
 ('A rise in core temperature due to fever','The defining direction is a further fall.'),('A delayed fall in platelet count after heparin','That is unrelated to cold rescue terminology.'),('Only skin cooling with a stable core temperature','Afterdrop concerns the core temperature.')],
 'Heat redistribution can continue during rescue','**Cold peripheral tissues and circulatory changes can contribute to further core cooling.**',['Rough handling and inappropriate peripheral exercise are undesirable.','Prevent additional environmental loss and manage the whole patient.'],'**Use controlled core-focused rewarming and monitor for instability.**',['Avoid forcing ambulation in a significantly impaired patient.','Assess for trauma, hypoglycemia and intoxication as contributors.'],[['Definition','Further core fall after rescue'],['Contributors','Redistribution/conduction'],['Response','Protected controlled rewarming']],[RC])

q('A patient in hypothermic cardiac arrest is being evaluated for extracorporeal rewarming. Which approach best supports prognostic selection?', 'Use a validated multivariable assessment such as HOPE together with the clinical context',[
 ('Declare futility from a single very low temperature','Low temperature alone does not establish irreversible injury.'),('Use serum potassium as the sole universal exclusion criterion','Potassium is relevant but should not replace the broader assessment.'),('Apply a normothermic arrest duration cutoff without modification','Hypothermia changes the context and recovery potential.')],
 'Hypothermic arrest has a distinct prognostic framework','**Potentially reversible cooling can protect organs while also causing arrest.**',['Asphyxia, trauma, comorbidity and rescue circumstances affect prognosis.','Validated models combine multiple variables rather than one number.'],'**Discuss early with an experienced ECLS center.**',['Continue appropriate resuscitation while determining candidacy.','Use the current regional hypothermia algorithm for drug and shock modifications.'],[['Selection','Multivariable model/context'],['Single temperature','Insufficient'],['Definitive option','Extracorporeal rewarming in suitable patients']],[RC],style='clinical_scenario')

q('For a conscious, stable patient with mild hypothermia, which approach is appropriate?', 'Shelter, dry insulation, active external warming and warm carbohydrate-containing drinks if swallowing is safe',[
 ('Oral alcohol to produce peripheral vasodilation','Alcohol impairs judgment and thermoregulation and is not treatment.'),('Leave wet clothing in place in a warm shelter','Wet clothing can perpetuate heat loss when it can be safely removed.'),('Immediate invasive extracorporeal rewarming for every mild case','That is disproportionate in a stable mild presentation.')],
 'Match rewarming intensity to severity','**A stable mildly cold patient can often rewarm with protection and external heat.**',['Calories support shivering thermogenesis.','Oral intake requires intact consciousness and safe swallowing.'],'**Observe the trajectory and escalate if recovery is inadequate.**',['Investigate precipitating illness in older or indoor patients.','Avoid burns from direct high-temperature contact.'],[['Stable mild illness','External/supportive warming'],['Oral fluids','Only if safe'],['Escalation','Instability or poor recovery']],[RC],style='clinical_scenario')

q('When is rapid thawing of a frostbitten extremity appropriate?', 'When the tissue can remain thawed and refreezing can be prevented',[
 ('Immediately even when unavoidable refreezing will follow','Freeze–thaw–refreeze injury can worsen tissue loss.'),('Only after rubbing it vigorously with snow','Mechanical trauma damages frozen tissue.'),('Only after directly heating it against a fire','Uncontrolled heat risks burns to insensate tissue.')],
 'Refreezing changes the immediate strategy','**Rapid controlled water-bath rewarming is used when sustained thawing is feasible.**',['Protect the frozen part during evacuation if refreezing cannot be prevented.','Treat significant hypothermia before focusing on the extremity.'],'**Use the recommended water temperature and provide analgesia.**',['Avoid walking on thawed injured feet when possible.','Protect tissue and arrange specialist assessment.'],[['Safe setting','Thaw and maintain warmth'],['Refreezing risk','Protect and plan evacuation'],['Avoid','Rubbing/direct fire']],[FR])

q('Which water-bath temperature is recommended for controlled rapid frostbite rewarming?', '37–39°C',[
 ('10–15°C','This is not the recommended rapid-thawing range.'),('50–55°C','This risks thermal burns, especially in insensate tissue.'),('70°C or hotter for a shorter duration','Extreme heat causes additional tissue destruction.')],
 'Warm enough to thaw, not hot enough to burn','**Controlled rewarming aims for tissue reperfusion without thermal injury.**',['Check water temperature with an accurate thermometer.','Rewarming can be intensely painful and requires analgesia.'],'**Continue until the tissue is thawed according to the protocol.**',['Protect the limb afterward and assess depth and perfusion.','Deep injury may warrant time-sensitive specialist therapies.'],[['Bath','37–39°C'],['Safety','Measured temperature'],['Afterward','Protection and specialist assessment']],[FR])

q('A patient has deep frostbite with poor perfusion after rewarming. Which management principle is appropriate?', 'Urgent specialist assessment for time-sensitive therapies such as iloprost or selected thrombolysis',[
 ('Wait several weeks before any vascular assessment','Potential salvage windows can close before late demarcation.'),('Give thrombolysis to every superficial frostnip injury','Therapy requires severity, timing and bleeding-risk selection.'),('Perform immediate amputation of all discolored digits','Appearance immediately after thawing does not reliably define final viability.')],
 'Early salvage decisions differ from late surgical decisions','**Microvascular injury and thrombosis can threaten deep tissue.**',['Treatment eligibility depends on injury depth, timing and contraindications.','Iloprost and thrombolysis have different indications and risk profiles.'],'**Transfer early and preserve tissue while the plan is made.**',['Protect blisters and wounds according to specialist guidance.','Reserve urgent surgery for specific complications rather than color alone.'],[['Early','Salvage assessment'],['Medical options','Selected iloprost/thrombolysis'],['Amputation','Usually requires later viability assessment']],[FR],style='clinical_scenario')

q('A trekker develops numb feet after prolonged wet exposure above freezing, with pain and swelling on rewarming but no tissue freezing. Which diagnosis is most likely?', 'Nonfreezing cold injury such as trench foot',[
 ('Frostbite by definition','Frostbite requires tissue freezing.'),('Heatstroke','The environmental exposure and local pattern differ.'),('Acute arterial embolism as established by wet exposure alone','Vascular occlusion is a differential but not the characteristic exposure syndrome.')],
 'Cold injury can occur without ice formation','**Prolonged wet cold can injure nerves and microvasculature above freezing temperatures.**',['Avoid confusing this with a frozen extremity requiring a rapid thawing bath.','Chronic neuropathic pain and cold sensitivity may follow.'],'**Remove wet exposure, protect the limb and obtain appropriate assessment.**',['Avoid friction, pressure and repeated cold exposure.','Evaluate perfusion and exclude alternative ischemic or infectious causes.'],[['Frostbite','Frozen tissue'],['Nonfreezing cold injury','Prolonged wet cold'],['Sequelae','Neuropathic symptoms/cold sensitivity']],[FR],style='clinical_scenario')
